#!/opt/homebrew/bin/bash
# bonds in the map (10-29 00:31/00:40): h21's and h22's rail A NICs and c1's bond0 are bonds whose members see
# the leaf. h21's ens3np0 member is down and, as a down port in the field, sends no LLDP (the operator 01:42): it gets a stub
# to a marker, never a link to a leaf nobody saw, and its panel infers the leaf from h22's ens3np0; h22's ens3np0 is
# down but still reports its switch: the red dashed edge to leaf1. The map draws a bond node per bond, a trunk from
# the host, one edge per member (the member NIC as the label); every title starts with the host's own names, the
# switch side sits in each edge's panel; the LLDP table shows the port id and the description
# secs: 80
# checks: 23
source "$(dirname "${BASH_SOURCE[0]}")/../lib.sh" "$@"
NETS=198.19.10.0/24,198.19.11.0/24

out=$(xrun bd FF_HOSTS=198.18.0.21-24 FF_CLIENTS=198.18.1.1-4 FF_CLIENT_NETS=$NETS FAKE_BOND_LLDP=h21,h22,c1 FAKE_BOND_DOWN=h21 FAKE_BOND_DOWN_SEEN=h22 FF_ITER=1 timeout 240 $B $C 1); rc=$?
chk "bonded run (4 backends, so nobody sits out at FF_ITER=1): rc 0, hosts 4/4, clients 4/4; the log names h21's and h22's slave down" "[ $rc = 0 ] && grep -qE '^RESULT coverage=COMPLETE hosts=4/4 .*clients=4/4' <<<\"\$out\" && grep -qx '#   h21 enp5s0np0 200000Mb/s (rail A): 1 of 2 slaves up, ens3np0 down (MII)' <<<\"\$out\" && grep -qx '#   h22 enp5s0np0 200000Mb/s (rail A): 1 of 2 slaves up, ens3np0 down (MII)' <<<\"\$out\"" "rc=$rc $(grep -E '^RESULT|ERROR|slaves up' <<<"$out" | head -n 3)"
chk "bonds.txt: h21's and h22's bonds 1 of 2 up (ens3np0 down), c1's bond0 2 of 2 up; no row for h23 or c2 (control)" \
    "[ \"\$(bfile bd bonds.txt | sort | tr '\n' '|')\" = 'c1 bond0 2 2 none|h21 enp5s0np0 1 2 ens3np0|h22 enp5s0np0 1 2 ens3np0|' ]" "$(bfile bd bonds.txt | tr '\n' '|')"
chk "LLDP rows: c1's bond0 row names no neighbour, its members ens1f0 (swp41) and ens1f1 (swp51) see cleaf1 on the bond's IP; c2's bond0 sees cleaf1 directly (control); h21's down ens3np0 names no switch, h22's down ens3np0 still names leaf1" \
    "[ \"\$(bfile bd lldp_neighbors.txt | grep '^c1 ' | awk '{print \$2, \$3, \$4, \$5}' | sort | tr '\n' '|')\" = 'bond0 198.19.10.1 unknown unknown|ens1f0 198.19.10.1 cleaf1.example swp41|ens1f1 198.19.10.1 cleaf1.example swp51|' ] && [ \"\$(bfile bd lldp_neighbors.txt | grep '^c2 ' | awk '{print \$2, \$4}')\" = 'bond0 cleaf1.example' ] && [ \"\$(bfile bd lldp_neighbors.txt | awk '\$2 == \"ens3np0\" {print \$1, \$4}' | sort | tr '\n' '|')\" = 'h21 unknown|h22 leaf1.example|' ]" "$(bfile bd lldp_neighbors.txt | grep '^c[12] \|ens3np0' | tr '\n' '|')"

render bd; prc=$?
nodes() { grep '^    var topoNodesData = ' "$1" | sed 's/^    var topoNodesData = //; s/;$//'; }
edges() { grep '^    var topoEdgesData = ' "$1" | sed 's/^    var topoEdgesData = //; s/;$//'; }
chk "map nodes: exactly 3 bond nodes, h21|enp5s0np0 and h22|enp5s0np0 (1 of 2 members up) and c1|bond0 (2 of 2), group bond; the hosts and clients at level 3 (bonds between the leaves and the hosts)" \
    "[ $prc = 0 ] && [ \"\$(nodes $W/bd.html | jq -c '[.[] | select(.group == \"bond\") | [.id, .host, .label, (.title | test(\"1 of 2 members up\")), (.title | test(\"2 of 2 members up\"))]] | sort')\" = '[[\"c1|bond0\",\"c1\",\"bond0 198.19.10.1\",false,true],[\"h21|enp5s0np0\",\"h21\",\"enp5s0np0 198.19.1.21\",true,false],[\"h22|enp5s0np0\",\"h22\",\"enp5s0np0 198.19.1.22\",true,false]]' ] && [ \"\$(nodes $W/bd.html | jq -c '[.[] | select(.group == \"host\" or .group == \"client\") | .level] | unique')\" = '[3]' ]" \
    "rc=$prc $(nodes $W/bd.html | jq -c '[.[] | select(.group == "bond") | [.id, .host, .label]]')"
chk "map edges: 3 trunks (host -> bond node) flagged bondtrunk with a bond panel naming the members and the count up" \
    "[ \"\$(edges $W/bd.html | jq -c '[.[] | select(.bondtrunk == true) | [.from, .to, .panel.kind, .panel.members, .panel.up, .panel.total]] | sort')\" = '[[\"c1\",\"c1|bond0\",\"bond\",[\"ens1f0\",\"ens1f1\"],2,2],[\"h21\",\"h21|enp5s0np0\",\"bond\",[\"ens1np0\",\"ens3np0\"],1,2],[\"h22\",\"h22|enp5s0np0\",\"bond\",[\"ens1np0\",\"ens3np0\"],1,2]]' ]" \
    "$(edges $W/bd.html | jq -c '[.[] | select(.bondtrunk == true) | [.from, .to, .panel.members, .panel.up]]' | cut -c1-300)"
chk "map edges: 6 member edges labelled by the member NIC, panel kind member, coloured by member state only (10-29 02:08): down = #e94560 dashed [4,4] (h22's seen ens3np0 to leaf1 swp122, h21's unseen ens3np0 to its marker), up = grey #8899aa solid (the other four, c1's included although c1 is a client); control: c2's plain client link keeps the client dash and h23's plain link the host colour" \
    "[ \"\$(edges $W/bd.html | jq -c '[.[] | select(.panel.kind == \"member\") | [.from, .to, .label, .panel.port_id, .panel.member_down, .color.color, .dashes]] | sort')\" = '[[\"c1|bond0\",\"cleaf1.example\",\"ens1f0\",\"swp41\",false,\"#8899aa\",false],[\"c1|bond0\",\"cleaf1.example\",\"ens1f1\",\"swp51\",false,\"#8899aa\",false],[\"h21|enp5s0np0\",\"h21|ens3np0\",\"ens3np0\",\"unknown\",true,\"#e94560\",[4,4]],[\"h21|enp5s0np0\",\"leaf1.example\",\"ens1np0\",\"swp21\",false,\"#8899aa\",false],[\"h22|enp5s0np0\",\"leaf1.example\",\"ens1np0\",\"swp22\",false,\"#8899aa\",false],[\"h22|enp5s0np0\",\"leaf1.example\",\"ens3np0\",\"swp122\",true,\"#e94560\",[4,4]]]' ] && [ \"\$(edges $W/bd.html | jq -c '.[] | select(.name == \"c2 bond0\") | [.dashes, (.color.color == \"#8899aa\")]')\" = '[[6,4],false]' ] && [ \"\$(edges $W/bd.html | jq -c '.[] | select(.name == \"h23 enp5s0np0\") | [.dashes, (.color.color | test(\"^#(4ecca3|0dcaf0|ffc107|e94560)$\"))]')\" = '[false,true]' ]" \
    "$(edges $W/bd.html | jq -c '[.[] | select(.panel.kind == "member") | [.from, .label, .panel.member_down, .color.color, .dashes]]')"
# the no-switch member (10-29 01:42: a real down port usually sends no LLDP): a marker node, a stub edge, never
# an edge to 'unknown'; its panel says no switch seen and infers the leaf from h22's ens3np0; c1 (every member seen)
# has no marker, the control
chk "no-switch member: one marker node h21|ens3np0 (group stub, host h21, bond h21|enp5s0np0, label '✕ ens3np0', tooltip 'down, no switch seen' and nothing about where it might land); 0 markers for c1 or h22 (control); 0 edges to or from 'unknown'" \
    "[ \"\$(nodes $W/bd.html | jq -c '[.[] | select(.group == \"stub\") | [.id, .host, .bond, .label, .level, (.title == \"h21 ens3np0 (member of enp5s0np0) 198.19.1.21: down, no switch seen\")]]')\" = '[[\"h21|ens3np0\",\"h21\",\"h21|enp5s0np0\",\"✕ ens3np0\",2,true]]' ] && [ \$(edges $W/bd.html | jq '[.[] | select(.to == \"unknown\" or .from == \"unknown\")] | length') = 0 ]" \
    "$(nodes $W/bd.html | jq -c '[.[] | select(.group == "stub") | [.id, .host, .bond, .label, .title]]')"
chk "no-switch member's stub edge: from the bond node to the marker, flagged stub, panel kind member with member_down and no_switch; h22's seen member has no_switch false (control); no guess at a leaf anywhere (10-29 01:58): 0 'inferred' or 'Expected leaf' in the page's titles, panels or JS (control: the build before this one had both)" \
    "[ \"\$(edges $W/bd.html | jq -c '.[] | select(.stub == true) | [.from, .to, .label, .panel.kind, .panel.member_down, .panel.no_switch, .panel.member_of, (.panel | has(\"expect\"))]')\" = '[\"h21|enp5s0np0\",\"h21|ens3np0\",\"ens3np0\",\"member\",true,true,\"enp5s0np0\",false]' ] && [ \"\$(edges $W/bd.html | jq -c '.[] | select(.from == \"h22|enp5s0np0\" and .label == \"ens3np0\") | [.stub, .panel.no_switch]')\" = '[false,false]' ] && [ \$(grep -c 'inferred\\|Expected leaf' $W/bd.html) = 0 ]" \
    "$(edges $W/bd.html | jq -c '.[] | select(.stub == true) | .panel')"
chk "map edges: the plain links keep panel kind link (h21 and h22 rail B, h23-h24 both rails, c2-c3 bond0, c4 two NICs = 10; 19 non-uplink edges with the 3 trunks and 6 members), every non-uplink edge carries name, ip and a numeric gbps (the legend, the exclude list and the speed filter read those, not the title)" \
    "[ \$(edges $W/bd.html | jq '[.[] | select(.panel.kind == \"link\")] | length') = 10 ] && [ \$(edges $W/bd.html | jq '[.[] | select(.uplink != true) | select((.name | type) != \"string\" or (.ip | type) != \"string\" or (.gbps | type) != \"number\")] | length') = 0 ] && [ \$(edges $W/bd.html | jq '[.[] | select(.uplink != true)] | length') = 19 ]" \
    "$(edges $W/bd.html | jq -c '[.[] | .panel.kind] | group_by(.) | map({(.[0] // "none"): length}) | add')"
chk "host-reported names: every non-uplink edge title starts with its host's name (the member edges included, whose from is the bond node); 0 non-uplink titles, labels or node tooltips carry a switch port id or description (swp, FE port); control: the LLDP table on the same page carries 'FE port c1 ens1f0'; vis shows tags literally, so 0 node or edge titles contain '<' (control: the 42e307a page has 20+); 0 titles contain 'unknown' (a member with no switch reads 'no switch seen'; control: the a24cfb5 page has 2 node + 1 edge titles with it)" \
    "[ \$(edges $W/bd.html | jq '[.[] | select(.uplink != true) | select((.title | split(\" \")[0]) != .panel.host)] | length') = 0 ] && [ \$(edges $W/bd.html | jq '[.[] | select(.title // \"\" | test(\"<|unknown\"))] | length') = 0 ] && [ \$(nodes $W/bd.html | jq '[.[] | select(.title // \"\" | test(\"<|unknown\"))] | length') = 0 ] && [ \"\$(nodes $W/bd.html | jq -r '.[] | select(.id == \"h21|enp5s0np0\") | .title')\" = \"\$(printf 'h21 enp5s0np0 198.19.1.21: 1 of 2 members up\nens1np0 → leaf1.example\nens3np0 → no switch seen (down)')\" ] &&[ \$(edges $W/bd.html | jq '[.[] | select(.uplink != true) | select(((.title // \"\") + (.label // \"\")) | test(\"swp|FE port\"))] | length') = 0 ] && [ \$(nodes $W/bd.html | jq '[.[] | select((.title // \"\") | test(\"swp|FE port\"))] | length') = 0 ] && [ \$(grep -c 'FE port c1 ens1f0' $W/bd.html) -ge 1 ]" \
    "$(edges $W/bd.html | jq -c '[.[] | select(.uplink != true) | .title]' | cut -c1-300)"
chk "panel data: a host link panel carries host, role, nic, ip, gbps, leaf, port_id, port_desc, sys_desc (h23 enp5s0np0 on leaf1 swp23, 'FE port 23', 'Cumulus Linux'); uplink edges carry a panel of kind uplink" \
    "[ \"\$(edges $W/bd.html | jq -c '.[] | select(.name == \"h23 enp5s0np0\") | .panel | [.kind, .host, .role, .nic, .ip, .leaf, .port_id, .port_desc, .sys_desc, (.gbps | type), .down]')\" = '[\"link\",\"h23\",\"backend\",\"enp5s0np0\",\"198.19.1.23\",\"leaf1.example\",\"swp23\",\"FE port 23\",\"Cumulus Linux\",\"number\",false]' ] && [ \$(edges $W/bd.html | jq '[.[] | select(.uplink == true) | select(.panel.kind != \"uplink\")] | length') = 0 ] && [ \$(edges $W/bd.html | jq '[.[] | select(.uplink == true)] | length') -ge 1 ]" \
    "$(edges $W/bd.html | jq -c '.[] | select(.name == "h23 enp5s0np0") | .panel')"
chk "LLDP table: the header has Switch Port then Port Description, once; c1's ens1f0 row shows swp41 then 'FE port c1 ens1f0'" \
    "[ \$(grep -c '<th>Switch</th><th>Switch Port</th><th>Port Description</th><th>LLDP Sys</th>' $W/bd.html) = 1 ] && grep -q '<td>c1</td><td>ens1f0</td><td>198.19.10.1</td><td>cleaf1.example</td><td>swp41</td><td>FE port c1 ens1f0</td>' $W/bd.html" \
    "$(grep -o '<td>c1</td><td>ens1f0</td>.\{0,120\}' $W/bd.html | head -n 1)"
# the map's gestures (10-29 01:15-01:20, 3b 01:20-01:38): a tap on a link opens its panel, a tap on blank space
# closes it; one double-click handler (puts a node back), no hold handler; nothing reads an edge title any more
chk "map JS: one click handler acting on taps only (p.event.type !== 'tap' once), blank taps call topoHidePanel, the toolbar's Uplinks button opens the drawer by topoShowPanel; 1 doubleClick (3b), 0 on('hold', 0 e.title.split" \
    "[ \$(grep -c \"p.event.type !== 'tap'\" $W/bd.html) = 1 ] && [ \$(grep -c 'else topoHidePanel();' $W/bd.html) = 1 ] && grep -q 'window.topoHidePanel = function' $W/bd.html && grep -q 'onclick=\"topoShowPanel('\"'\"'uplinks'\"'\"')\">Uplinks</button>' $W/bd.html && [ \$(grep -c \"on('doubleClick'\" $W/bd.html) = 1 ] && [ \$(grep -c \"on('hold'\" $W/bd.html) = 0 ] && [ \$(grep -c 'e.title.split' $W/bd.html) = 0 ]" \
    "$(grep -o "on('[a-zA-Z]*'" $W/bd.html | sort | uniq -c | tr '\n' ' ')"
chk "node panels (3b): the 3 bond nodes carry a panel of kind bond with 2 members and their leaves (h21: ens1np0 on leaf1, ens3np0 down with no switch seen), the marker node a member panel with no_switch true, hosts and clients a host panel whose bond NIC lists its members; 0 nodes without a panel" \
    "[ \"\$(nodes $W/bd.html | jq -c '[.[] | select(.group == \"bond\") | .panel | [.kind, (.members | length), (.leaves | length)]] | unique')\" = '[[\"bond\",2,2]]' ] && [ \"\$(nodes $W/bd.html | jq -c '.[] | select(.id == \"h21|enp5s0np0\") | .panel.leaves')\" = '[{\"nic\":\"ens1np0\",\"leaf\":\"leaf1.example\",\"down\":false},{\"nic\":\"ens3np0\",\"leaf\":\"no switch seen\",\"down\":true}]' ] && [ \"\$(nodes $W/bd.html | jq -c '[.[] | select(.group == \"stub\") | .panel | [.kind, .no_switch, .member_down]]')\" = '[[\"member\",true,true]]' ] && [ \"\$(nodes $W/bd.html | jq -c '.[] | select(.id == \"h21\") | .panel.nics[] | select(.nic == \"enp5s0np0\") | [.members[].nic]')\" = '[\"ens1np0\",\"ens3np0\"]' ] && [ \$(nodes $W/bd.html | jq '[.[] | select(.panel == null)] | length') = 0 ]" \
    "$(nodes $W/bd.html | jq -c '[.[] | .panel.kind] | group_by(.) | map({(.[0] // "none"): length}) | add')"
chk "drawer: the offcanvas holds the uplinks card (#topoUplinksCard) and the link pane (#topoLinkPanel, hidden) under one title (#topoPanelTitle); the legend's down count and the exclude list read e.ip / e.name" \
    "grep -q '<div id=\"topoUplinksCard\">' $W/bd.html && grep -q '<div id=\"topoLinkPanel\" style=\"display:none;\">' $W/bd.html && grep -q 'id=\"topoPanelTitle\"' $W/bd.html && grep -q 'if (downIps.has(e.ip) || (e.panel && e.panel.member_down)) {' $W/bd.html &&grep -q \"o.textContent = e.name + ' — ' + e.ip + ' → ' + (e.stub ? 'no switch seen' : e.to);\" $W/bd.html" \
    "$(grep -o 'id="topo[A-Za-z]*"' $W/bd.html | sort -u | tr '\n' ' ')"
# Radial: a bond node sits just inside its host (r 560 at the host's angle) and a host reaches its members' leaves
chk "Radial code: bonds pinned at R_HOST - 70 - (ring % 9) * 26 at their host's angle, markers 40 outside their bond a step aside each; leavesOf sees through a bond trunk; markers and bonds follow their host in the filters; the legend counts a down member as a down link" \
    "grep -q 'bondR\[n.id\] = R_HOST - 70 - (ringOf\[n.host\] % 9) \* 26;' $W/bd.html && grep -q 'pin(n, bondR\[n.id\], angleOf\[n.host\]);' $W/bd.html && grep -q 'pin(n, bondR\[n.bond\] + 40, angleOf\[n.host\] + 0.03 \* aside\[n.bond\]);' $W/bd.html &&grep -q 'if (e.bondtrunk) Object.keys(leavesOf\[e.to\] || {})' $W/bd.html && grep -q \"if (n.group === 'bond' || n.group === 'stub') nodeVis\[n.id\] = !!nodeVis\[n.host\];\" $W/bd.html && grep -q 'if (downIps.has(e.ip) || (e.panel && e.panel.member_down)) { lDown++; return; }' $W/bd.html" "$(grep -o 'pin(n, [56][0-9][0-9][^;]*' $W/bd.html | tr '\n' ' ')"
# NIC, leaf, host, bond and member panels through the page's own entry points (criterion 4, commit C; the probe's
# "panels" mode: window.topoNicPanel(ip) per NIC in topoNicData, window.topoShowPanel('node', id) per node, the drawer
# read back): every cell present or '-', 0 undefined/NaN/empty, every IP link titled with an onclick; 0 tab switches
# from the IP clicks (criterion 4's addition); the repair set empty on this run (A4)
node $S/fixtures/units/pageload_probe.js $W/bd.html panels > $W/pp.out 2>&1; pprc=$?
pj() { grep '^{"panels"' $W/pp.out | jq -r "$1"; }
chk "panels (44_bd): 13 NIC panels (8 with a run table, 5 clients' saying 'No backend runs for this NIC'), 3 leaf, 8 host, 3 bond, 1 member, 1 spine panels; 55 IP links over the NIC, leaf, host and member panels, every one titled with an onclick; 0 undefined/NaN/[object cells, 0 empty cells, 0 errors, 0 tab switches from the 13 IP clicks (control: the planted-error mode counts 1 error)" \
    "[ $pprc = 0 ] && [ \"\$(pj '[.panels.nic.n, .panels.nic.runs, .panels.nic.noruns, .panels.leaf.n, .panels.host.n, .panels.bond.n, .panels.member.n, .panels.spine.n] | join(\" \")')\" = '13 8 5 3 8 3 1 1' ] && [ \"\$(pj '[.panels.nic.links, .panels.leaf.links, .panels.host.links, .panels.member.links] | add')\" = 55 ] && [ \"\$(pj '[.panels.nic.linksOk, .panels.leaf.linksOk, .panels.host.linksOk, .panels.member.linksOk] | add')\" = 55 ] && [ \"\$(pj '[.panels[] | .bad, .empty] | add')\" = 0 ] && [ \"\$(pj '.panel_errors')\" = 0 ] && [ \"\$(pj '.panels.nic.tab_shows_by_ip_clicks')\" = 0 ] && [ \"\$(node $S/fixtures/units/pageload_probe.js $W/bd.html planted | grep '^{\"errors\"' | jq '.errors | length')\" = 1 ]" \
    "rc=$pprc $(grep '^{\"panels\"' $W/pp.out | cut -c1-400)"
chk "Needs Repair (44_bd, A4): 0 NICs need repair: header '<b class=\"stat-good\">0</b> need repair |', label 'Needs Repair (0)' with a green dot, 'No NIC needs repair.', Connection Health green too (control: a planted red header counts 1)" \
    "grep -qF '<b class=\"stat-good\">0</b> need repair |' $W/bd.html && grep -q 'href=\"#tab-slow\">Needs Repair (0) <span class=\"tab-dot\" style=\"background:#4ecca3;\"' $W/bd.html && grep -qF 'No NIC needs repair.' $W/bd.html && grep -q 'href=\"#tab-connections\">Connection Health <span class=\"tab-dot\" style=\"background:#4ecca3;\"' $W/bd.html && [ \$({ cat $W/bd.html; echo '<b class=\"stat-bad\">1</b> need repair |'; } | grep -c 'need repair |') = 2 ]" \
    "$(grep -o '<b class=\"stat-[a-z]*\">[0-9]*</b> need repair' $W/bd.html | head -n 1) | $(grep -o 'href=\"#tab-slow\">[^<]*<span class=\"tab-dot\" style=\"background:#[0-9a-f]*' $W/bd.html | head -n 1)"
chk "control: a host with no bond (h23) gets two plain links and no bond node or marker; the run's log counted 3 bonds" \
    "[ \$(edges $W/bd.html | jq '[.[] | select(.from == \"h23\")] | length') = 2 ] && [ \$(nodes $W/bd.html | jq '[.[] | select((.group == \"bond\" or .group == \"stub\") and .host == \"h23\")] | length') = 0 ] && grep -q 'Diagnostics: .* driver lines, 3 bonds' <<<\"\$out\"" "$(grep 'Diagnostics:' <<<"$out")"
# a client bond's leaf = its members' leaves joined "+"; "no switch seen" only when no member saw one (10-29 23:05).
# Seven critical NICs, four Where groups (all it shows): c1 on cleaf1+cleaf2, c2 one member dark, c3 both dark;
# controls: c4's plain NICs, the backends' one rail
out=$(xrun cb FAKE_RAILS=1 FF_RAILS=198.19.1.0/24 FF_HOSTS=198.18.0.21-22 FF_CLIENTS=198.18.1.1-4 FF_CLIENT_NETS=$NETS FAKE_BOND_LLDP=c1,c2,c3 FAKE_BOND_LEAF2=c1 FAKE_BOND_DARK=c2 FAKE_NO_LLDP=c3 FAKE_SLOW_IP=198.19.10.1,198.19.10.2,198.19.10.3,198.19.10.4,198.19.11.4 FF_ITER=1 timeout 40 $B $C 1); rc=$?
render cb; prc=$?
where() { grep -o '<ul class="where-list mb-0">.*' "$1" | head -n 1 | sed 's#</ul>.*##' | sed 's#<li#\n<li#g' | grep '^<li'; }
nicdata() { grep '^    var topoNicData = ' "$1" | sed 's/^    var topoNicData = //; s/, topoLeafData = .*$//; s/;$//'; }
chk "grouped Where line (cb): '7 NICs ran slow or are down (' with '3 client NICs on cleaf1.example' (c2, c4), '2 backend NICs on leaf1.example' (control), '1 client NICs on cleaf1.example+cleaf2.example' (c1), '1 client NICs on no switch seen' (c3); 'no switch seen' once = all-dark bond nodes on the map (1); 0 per-NIC lines" \
    "[ $rc = 0 ] && [ $prc = 0 ] && where $W/cb.html | grep -q '7 NICs ran slow or are down (' && where $W/cb.html | grep -q '3 client NICs on cleaf1.example[,)]' && where $W/cb.html | grep -q '2 backend NICs on leaf1.example[,)]' && where $W/cb.html | grep -q '1 client NICs on cleaf1.example+cleaf2.example[,)]' && where $W/cb.html | grep -q '1 client NICs on no switch seen[,)]' && [ \$(where $W/cb.html | grep -o 'no switch seen' | wc -l | tr -d ' ') = 1 ] && [ \$(edges $W/cb.html | jq '[.[] | select(.panel.kind == \"member\")] | group_by(.from) | map(select(all(.panel.no_switch))) | length') = 1 ] && [ \$(where $W/cb.html | grep -c '% of expected at worst') = 0 ]" \
